/**
 * ⚠️ NOTICE TO AI AGENTS / AUTOMATION ⚠️
 * DO NOT EDIT THIS FILE OR ANY OTHER FILES IN scripts/!
 */

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { execSync } from 'node:child_process';

const ROOT_DIR = process.cwd();
const LAST_CYCLE_DIR = path.join(ROOT_DIR, 'doc', 'LAST_CYCLE');
const STATE_JSON_PATH = path.join(LAST_CYCLE_DIR, 'STATE.json');
const REQUIRED_TOKEN_PATH = path.join(LAST_CYCLE_DIR, 'REQUIRED_TOKEN.txt');
const APPROVAL_PATH = path.join(LAST_CYCLE_DIR, 'APPROVAL.md');
const CYCLE_LOG_PATH = path.join(LAST_CYCLE_DIR, 'CYCLE_LOG.md');

const CYCLE_SALT = process.env.OCE_HMAC_SECRET || 'OCE_v10.2_HMAC_SALT_SECRET';
const STEP_SEQUENCE = [
  '1a', '0a', '0b',
  '1b', '2a', '2b', '2c', '2d',
  '3a', '3b', '2e', '3c'
];

function verifyScriptsNotModified() {
  try {
    const gitLog = execSync('git log -n 1 --oneline', { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] }).trim();
    if (!gitLog) {
      console.error('❌ [INTEGRITETSFEL] Ingen Git-historik hittades.');
      process.exit(1);
    }
  } catch {
    console.error('❌ [INTEGRITETSFEL] Ej ett giltigt Git-arkiv. Körning nekas.');
    process.exit(1);
  }

  const diff = execSync('git status --porcelain scripts/', { encoding: 'utf8' }).trim();
  if (diff.length > 0) {
    console.error('❌ [INTEGRITETSFEL] Ändringar upptäckta i scripts/-mappen!');
    console.error(diff);
    process.exit(1);
  }
}

function calculateHMAC(data, prevHash) {
  return crypto.createHmac('sha256', CYCLE_SALT)
    .update(`${prevHash}:${data}`)
    .digest('hex')
    .substring(0, 16);
}

function resolveTicketTarget() {
  const args = process.argv.slice(2);
  if (args[0] && args[0].startsWith('TCK-')) return args[0];

  const promptPath = path.join(ROOT_DIR, 'PROMPT.md');
  if (fs.existsSync(promptPath)) {
    const promptContent = fs.readFileSync(promptPath, 'utf8');
    const match = promptContent.match(/AKTIVT UPPDRAG:\s*(TCK-\d+[a-z]?)/i);
    if (match) return match[1];
  }
  return null;
}

function runBygg() {
  verifyScriptsNotModified();

  const ticket = resolveTicketTarget();
  if (!ticket) {
    console.error('❌ [BYGG] Ingen giltig TCK hittades i argument eller PROMPT.md.');
    process.exit(1);
  }

  console.log(`🔍 [BYGG v10.3] Granskar arkitekturplanering för ${ticket}...`);

  if (!fs.existsSync(CYCLE_LOG_PATH)) {
    console.error(`❌ [PLANERING SAKNAS] Filen doc/LAST_CYCLE/CYCLE_LOG.md saknas.`);
    console.error(`   Byggmotorn måste formulera steg 1a-3c i CYCLE_LOG.md innan bygget kan låsas upp.`);
    process.exit(1);
  }

  const logContent = fs.readFileSync(CYCLE_LOG_PATH, 'utf8');
  const stepContents = {};

  // Validera att varje steg finns och innehåller genuin analys
  for (const step of STEP_SEQUENCE) {
    const regex = new RegExp(`## Steg ${step}[\\r\\n]+([\\s\\S]*?)(?=(## Steg |$))`);
    const match = logContent.match(regex);
    const text = match ? match[1].trim() : '';

    if (!text || text.length < 40) {
      console.error(`❌ [OTILLRÄCKLIG PLANERING] Steg ${step} saknar analys i CYCLE_LOG.md (minst 40 tecken krävs).`);
      process.exit(1);
    }

    if (text.toLowerCase().includes('automatiserat steg') || text.toLowerCase().includes('inga externa brott')) {
      console.error(`❌ [DUMMY-TEXT AVVISAD] Steg ${step} innehåller fördefinierad platshållartext. Genuin analys krävs.`);
      process.exit(1);
    }

    stepContents[step] = text;
  }

  console.log(`✅ [PLANERING GODKÄND] Samtliga 12 delsteg granskade och godkända.`);

  // Beräkna HMAC baserat på agentens faktiska analysord
  let state = {
    ticket,
    completed_steps: [],
    current_hash: 'GENESIS',
    history: []
  };

  for (const step of STEP_SEQUENCE) {
    const stepHash = calculateHMAC(`${step}:${stepContents[step]}`, state.current_hash);
    state.completed_steps.push(step);
    state.current_hash = stepHash;
    state.history.push({ step, hash: stepHash, timestamp: new Date().toISOString() });
  }

  fs.writeFileSync(STATE_JSON_PATH, JSON.stringify(state, null, 2), 'utf8');

  // Generera token och bevara historiska tokens i APPROVAL.md
  const finalToken = `${ticket}-VERIFIED-${state.current_hash}`;
  fs.writeFileSync(REQUIRED_TOKEN_PATH, finalToken, 'utf8');

  let existingApprovals = fs.existsSync(APPROVAL_PATH) ? fs.readFileSync(APPROVAL_PATH, 'utf8') : '';
  const newEntry = `APPROVED: ${finalToken}\nDATE: ${new Date().toISOString()}`;
  const fullApproval = existingApprovals.includes(finalToken)
    ? existingApprovals
    : (existingApprovals ? existingApprovals.trim() + '\n' + newEntry : newEntry);

  fs.writeFileSync(APPROVAL_PATH, fullApproval, 'utf8');

  console.log(`🔑 [TOKEN GENERERAD] ${finalToken}`);
  console.log(`🔓 [FAS 2 UPPLÅST] Källkodsredigering under src/ är öppen för ${ticket}.`);
  console.log(`▶️ Nästa steg: Kör TDD Fail First (transient_${ticket}.test.ts) och applicera källkod.`);
}

runBygg();